async function fetchSignals() {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/signals?select=*&order=created_at.desc`, {
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
    },
  });
  if (!res.ok) {
    throw new Error(`Error ${res.status} al leer las señales`);
  }
  const rows = await res.json();
  return rows.map((r) => ({
    id: r.id,
    par: r.par,
    direccion: r.direccion,
    estado: r.estado,
    pips: r.pips,
    entrada: Number(r.precio_entrada),
    sl: Number(r.stop_loss),
    tp: Number(r.take_profit),
    tipoOrden: r.tipo_orden,
    autor: r.autor,
    imagenUrl: r.imagen_url,
    fecha: r.created_at
      ? new Date(r.created_at).toLocaleString("es-AR", { dateStyle: "medium", timeStyle: "short" })
      : "",
  }));
}

