function computeStats(signals) {
  const closed = signals.filter((s) => s.estado === "ganada" || s.estado === "perdida");
  const wins = closed.filter((s) => s.estado === "ganada");
  const winRate = closed.length ? Math.round((wins.length / closed.length) * 100) : 0;
  const rrProm = 2;
  const neto = closed.length
    ? closed.reduce((acc, s) => acc + (s.estado === "ganada" ? s.pips : -s.pips), 0)
    : 0;
  return { winRate, rrProm, neto };
}

function CopyField({ label, value, formatted, color }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = () => {
    const text = formatted ?? String(value);
    if (navigator.clipboard) navigator.clipboard.writeText(text).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 1200);
  };
  return (
    <button
      onClick={handleCopy}
      className="flex-1 rounded-2xl px-4 py-4 text-left transition-colors"
      style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
    >
      <div className="flex items-center justify-between mb-1">
        <span className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>{label}</span>
        {copied ? <Check size={14} color={C.green} /> : <Copy size={13} color={C.textDim} />}
      </div>
      <div className="text-lg font-semibold font-mono" style={{ color: color || C.text }}>
        {formatted ?? value}
      </div>
    </button>
  );
}

