function formatSignalText(signal) {
  const dir = signal.direccion === "venta" ? "VENTA" : "COMPRA";
  const estadoInfo = ESTADO_STYLES[signal.estado] || { label: signal.estado };
  return [
    `📊 *${signal.par}* — ${dir}`,
    `Estado: ${estadoInfo.label}`,
    ``,
    `Entrada: ${formatPrice(signal.entrada)}`,
    `Stop Loss: ${formatPrice(signal.sl)}`,
    `Take Profit: ${formatPrice(signal.tp)}`,
    `Tipo de orden: ${signal.tipoOrden}`,
    ``,
    `Operación Trading — ${signal.autor}`,
  ].join("\n");
}

function CopySignalButton({ signal }) {
  const [status, setStatus] = useState(null); // "text" | "image" | "shared"

  const flash = (s) => {
    setStatus(s);
    setTimeout(() => setStatus(null), 1800);
  };

  const handleShare = async () => {
    const text = formatSignalText(signal);
    try {
      if (navigator.share) {
        let files = [];
        if (signal.imagenUrl) {
          const resp = await fetch(signal.imagenUrl);
          const blob = await resp.blob();
          const file = new File([blob], "senal.png", { type: blob.type || "image/png" });
          if (!navigator.canShare || navigator.canShare({ files: [file] })) {
            files = [file];
          }
        }
        await navigator.share(files.length ? { text, files } : { text });
        flash("shared");
        return;
      }
    } catch (err) {
      // el usuario canceló el share nativo, o no hay soporte: seguimos con el fallback
    }
    await navigator.clipboard.writeText(text);
    flash("text");
  };

  const handleCopyTextOnly = async () => {
    const text = formatSignalText(signal);
    await navigator.clipboard.writeText(text);
    flash("text");
  };

  const handleCopyImageOnly = async () => {
    if (!signal.imagenUrl) return;
    try {
      const resp = await fetch(signal.imagenUrl);
      const blob = await resp.blob();
      await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);
      flash("image");
    } catch (err) {
      flash(null);
    }
  };

  return (
    <div>
      <button
        onClick={handleShare}
        className="w-full flex items-center justify-center gap-2 rounded-2xl py-4 text-[15px] font-semibold"
        style={{
          backgroundColor: status === "shared" ? C.green : C.cardAlt,
          color: status === "shared" ? "#08090B" : C.text,
          border: `1px solid ${C.border}`,
        }}
      >
        {status === "shared" ? <Check size={18} /> : <Share2 size={18} />}
        {status === "shared" ? "¡Compartido!" : "Compartir señal (texto + imagen)"}
      </button>

      <div className="flex gap-2 mt-2">
        <button
          onClick={handleCopyTextOnly}
          className="flex-1 flex items-center justify-center gap-1.5 rounded-xl py-2.5 text-[12px] font-medium"
          style={{
            backgroundColor: status === "text" ? C.green : "transparent",
            color: status === "text" ? "#08090B" : C.textDim,
            border: `1px solid ${C.border}`,
          }}
        >
          {status === "text" ? <Check size={13} /> : <Copy size={13} />}
          {status === "text" ? "Texto copiado" : "Copiar solo texto"}
        </button>
        {signal.imagenUrl && (
          <button
            onClick={handleCopyImageOnly}
            className="flex-1 flex items-center justify-center gap-1.5 rounded-xl py-2.5 text-[12px] font-medium"
            style={{
              backgroundColor: status === "image" ? C.green : "transparent",
              color: status === "image" ? "#08090B" : C.textDim,
              border: `1px solid ${C.border}`,
            }}
          >
            {status === "image" ? <Check size={13} /> : <ImageIcon size={13} />}
            {status === "image" ? "Imagen copiada" : "Copiar solo imagen"}
          </button>
        )}
      </div>

      <p className="text-[11px] text-center mt-2" style={{ color: C.textDim }}>
        "Compartir" abre el menú nativo del celular (incluye WhatsApp) y manda texto e imagen juntos. En compu, usá los botones de copiar por separado.

      </p>
    </div>
  );
}

