const ESTADOS = ["pendiente", "activa", "ganada", "perdida", "descartada"];
const TIPOS_ORDEN = ["Buy Limit", "Sell Limit", "Buy Stop", "Sell Stop", "Market"];

function addMonths(dateStr, months) {
  if (!dateStr) return "";
  const d = new Date(dateStr + "T00:00:00");
  d.setMonth(d.getMonth() + months);
  return d.toISOString().slice(0, 10);
}

function formatPrice(n) {
  if (n === null || n === undefined || isNaN(n)) return "";
  // Redondea a 6 decimales (evita errores de coma flotante) y saca los ceros que sobran
  return parseFloat(Number(n).toFixed(6)).toString();
}

function calcPips(par, entrada, sl) {
  const e = Number(entrada);
  const s = Number(sl);
  if (!par || isNaN(e) || isNaN(s)) return null;
  const diff = Math.abs(e - s);
  const p = par.toUpperCase();
  let pipSize = 0.0001;
  if (p.includes("JPY")) pipSize = 0.01;
  else if (p.includes("XAU") || p.includes("XAG") || p.includes("GOLD")) pipSize = 1;
  const pips = diff / pipSize;
  return Math.round(pips * 10) / 10;
}

function AdminForm({ onClose, onCreated, existingSignal }) {
  const isEdit = !!existingSignal;
  const [par, setPar] = useState(existingSignal?.par || "");
  const [direccion, setDireccion] = useState(existingSignal?.direccion || "compra");
  const [precioEntrada, setPrecioEntrada] = useState(existingSignal ? String(existingSignal.entrada) : "");
  const [stopLoss, setStopLoss] = useState(existingSignal ? String(existingSignal.sl) : "");
  const [takeProfit, setTakeProfit] = useState(existingSignal ? String(existingSignal.tp) : "");
  const [tipoOrden, setTipoOrden] = useState(existingSignal?.tipoOrden || "Buy Limit");
  const [estado, setEstado] = useState(existingSignal?.estado || "pendiente");
  const [autor, setAutor] = useState(existingSignal?.autor || "");
  const [file, setFile] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  const pips = calcPips(par, precioEntrada, stopLoss);

  const canSubmit =
    par.trim() && precioEntrada && stopLoss && takeProfit && pips && autor.trim() && !submitting;

  const handleSubmit = async () => {
    setSubmitting(true);
    setError(null);
    try {
      let imagenUrl = existingSignal?.imagenUrl || null;
      if (file) {
        imagenUrl = await uploadChartImage(file);
      }
      const payload = {
        par: par.trim().toUpperCase(),
        direccion,
        precio_entrada: Number(precioEntrada),
        stop_loss: Number(stopLoss),
        take_profit: Number(takeProfit),
        tipo_orden: tipoOrden,
        estado,
        pips: Number(pips),
        autor: autor.trim(),
        imagen_url: imagenUrl,
      };
      if (isEdit) {
        await updateSignal(existingSignal.id, payload);
      } else {
        await createSignal(payload);
      }
      onCreated();
      onClose();
    } catch (err) {
      setError(err.message || "No se pudo guardar la señal");
    } finally {
      setSubmitting(false);
    }
  };

  const inputStyle = {
    backgroundColor: C.cardAlt,
    color: C.text,
    border: `1px solid ${C.border}`,
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center"
      style={{ backgroundColor: "rgba(0,0,0,0.6)" }}
      onClick={onClose}
    >
      <div
        className="rounded-t-3xl w-full max-w-md p-6 max-h-[85vh] overflow-y-auto"
        style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, borderBottom: "none" }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <span className="text-[15px] font-semibold" style={{ color: C.text }}>{isEdit ? "Editar señal" : "Nueva señal"}</span>
          <button onClick={onClose}>
            <X size={20} color={C.textDim} />
          </button>
        </div>

        <div className="flex flex-col gap-3">
          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>PAR</label>
            <input
              value={par}
              onChange={(e) => setPar(e.target.value)}
              placeholder="EUR/USD"
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={inputStyle}
            />
          </div>

          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>DIRECCIÓN</label>
            <div className="flex gap-2 mt-1">
              {["compra", "venta"].map((d) => (
                <button
                  key={d}
                  onClick={() => setDireccion(d)}
                  className="flex-1 rounded-xl py-2.5 text-sm font-semibold capitalize"
                  style={{
                    backgroundColor: direccion === d ? (d === "venta" ? C.red : C.green) : C.cardAlt,
                    color: direccion === d ? "#08090B" : C.textDim,
                    border: `1px solid ${C.border}`,
                  }}
                >
                  {d}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <div>
              <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>ENTRADA</label>
              <input
                value={precioEntrada}
                onChange={(e) => setPrecioEntrada(e.target.value)}
                inputMode="decimal"
                className="w-full mt-1 rounded-xl px-3 py-3 text-sm font-mono outline-none"
                style={inputStyle}
              />
            </div>
            <div>
              <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>SL</label>
              <input
                value={stopLoss}
                onChange={(e) => setStopLoss(e.target.value)}
                inputMode="decimal"
                className="w-full mt-1 rounded-xl px-3 py-3 text-sm font-mono outline-none"
                style={inputStyle}
              />
            </div>
            <div>
              <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>TP</label>
              <input
                value={takeProfit}
                onChange={(e) => setTakeProfit(e.target.value)}
                inputMode="decimal"
                className="w-full mt-1 rounded-xl px-3 py-3 text-sm font-mono outline-none"
                style={inputStyle}
              />
            </div>
          </div>

          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>TIPO DE ORDEN</label>
            <select
              value={tipoOrden}
              onChange={(e) => setTipoOrden(e.target.value)}
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={inputStyle}
            >
              {TIPOS_ORDEN.map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>ESTADO</label>
            <select
              value={estado}
              onChange={(e) => setEstado(e.target.value)}
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none capitalize"
              style={inputStyle}
            >
              {ESTADOS.map((e2) => (
                <option key={e2} value={e2}>{e2}</option>
              ))}
            </select>
          </div>

          {pips !== null && (
            <div className="text-sm text-center" style={{ color: C.textDim }}>
              Distancia al SL: <span className="font-mono font-semibold" style={{ color: C.text }}>{pips}</span> pips (calculado automáticamente)
            </div>
          )}

          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>TU NOMBRE (AUTOR)</label>
            <input
              value={autor}
              onChange={(e) => setAutor(e.target.value)}
              placeholder="Ej: Fede Lobo"
              className="w-full mt-1 rounded-xl px-4 py-3 text-[15px] outline-none"
              style={inputStyle}
            />
          </div>

          <div>
            <label className="text-[11px] tracking-wide font-medium" style={{ color: C.textDim }}>
              CAPTURA DEL GRÁFICO {isEdit && "(dejar vacío para mantener la actual)"}
            </label>
            <label
              className="mt-1 flex items-center justify-center gap-2 rounded-xl py-4 cursor-pointer"
              style={{ backgroundColor: C.cardAlt, border: `1px dashed ${C.border}` }}
            >
              <UploadCloud size={18} color={C.textDim} />
              <span className="text-sm" style={{ color: C.textDim }}>
                {file ? file.name : "Elegir imagen"}
              </span>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => setFile(e.target.files?.[0] || null)}
              />
            </label>
          </div>

          {error && (
            <div className="text-sm text-center" style={{ color: C.red }}>{error}</div>
          )}

          <button
            onClick={handleSubmit}
            disabled={!canSubmit}
            className="w-full rounded-2xl py-4 text-[15px] font-semibold mt-2"
            style={{
              backgroundColor: canSubmit ? C.green : C.borderSoft,
              color: canSubmit ? "#08090B" : C.textDim,
            }}
          >
            {submitting ? "Guardando..." : isEdit ? "Guardar cambios" : "Publicar señal"}
          </button>
        </div>
      </div>
    </div>
  );
}

